// A map on the Auto basemap gets a card image for each theme. The two
// bundled Auto styles are answered locally with distinct grounds, so a
// decoded image says which theme's style it was rendered on: the light
// image's ground is one colour, the dark image's another, and both carry
// the map's marks in the same place. Every host of the shared card
// follows a theme toggle with no reload; a map on a chosen basemap keeps
// one image; a single image that predates the feature serves both themes
// and is not regenerated by being listed. Run with DEZFIL_BASE_URL at an
// isolated instance.
import path from "node:path";
import { readFileSync } from "node:fs";
import { test, expect, type BrowserContext, type Locator, type Page } from "@playwright/test";
import {
  FIXTURES_DIR,
  addLayer,
  createMap,
  patchLayer,
  patchMap,
  routeHouse,
  seedCsv,
  trackConsole,
} from "./support";
import { isAllowedConsoleError } from "./console-allowlist";

const runId = Date.now().toString(36);
const tableName = `tt_${runId}`;

/** The map's marks: a constant fill every probe can find. */
const KELP = [26, 93, 74] as const;
/** The stubbed grounds, one per bundled style, none a fallback colour. */
const GROUNDS = {
  dark: { url: "/styles/dark", rgb: [26, 42, 58] as const, css: "#1a2a3a" },
  positron: { url: "/styles/positron", rgb: [240, 230, 200] as const, css: "#f0e6c8" },
  liberty: { url: "/styles/liberty", rgb: [200, 224, 240] as const, css: "#c8e0f0" },
};

/** Answer the three bundled OpenFreeMap styles locally, each one
 * background of its own colour; everything else third-party stays
 * aborted by the house policy. Registered after it, so it wins. */
async function stubStyles(context: BrowserContext) {
  await context.route("https://tiles.openfreemap.org/**", async (route) => {
    const { pathname } = new URL(route.request().url());
    const style = Object.values(GROUNDS).find((g) => g.url === pathname);
    if (!style) return route.abort();
    return route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify({
        version: 8,
        sources: {},
        layers: [
          { id: "background", type: "background", paint: { "background-color": style.css } },
        ],
      }),
    });
  });
}

interface ImageStats {
  width: number;
  height: number;
  /** The average colour of the top-left corner box, bare ground. */
  ground: [number, number, number];
  /** Pixels near the marks' fill, and where they sit as a share of the frame. */
  marks: number;
  cx: number;
  cy: number;
}

async function imageStats(page: Page, png: Buffer): Promise<ImageStats> {
  return page.evaluate(
    async ({ b64, kelp }) => {
      const raw = atob(b64);
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
      const bmp = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
      const c = document.createElement("canvas");
      c.width = bmp.width;
      c.height = bmp.height;
      const ctx = c.getContext("2d")!;
      ctx.drawImage(bmp, 0, 0);
      const { data } = ctx.getImageData(0, 0, c.width, c.height);
      const near = (i: number, t: readonly number[]) =>
        Math.abs(data[i] - t[0]) <= 24 &&
        Math.abs(data[i + 1] - t[1]) <= 24 &&
        Math.abs(data[i + 2] - t[2]) <= 24;
      let marks = 0;
      let sx = 0;
      let sy = 0;
      const sum = [0, 0, 0];
      let corner = 0;
      for (let y = 0; y < c.height; y += 1) {
        for (let x = 0; x < c.width; x += 1) {
          const i = (y * c.width + x) * 4;
          if (x < c.width * 0.08 && y < c.height * 0.08) {
            sum[0] += data[i];
            sum[1] += data[i + 1];
            sum[2] += data[i + 2];
            corner += 1;
          }
          if (near(i, kelp)) {
            marks += 1;
            sx += x;
            sy += y;
          }
        }
      }
      return {
        width: c.width,
        height: c.height,
        ground: sum.map((v) => Math.round(v / corner)) as [number, number, number],
        marks,
        cx: marks ? sx / marks / c.width : 0,
        cy: marks ? sy / marks / c.height : 0,
      };
    },
    { b64: png.toString("base64"), kelp: [...KELP] },
  );
}

const closeTo = (a: readonly number[], b: readonly number[], tol = 12) =>
  a.every((v, i) => Math.abs(v - b[i]) <= tol);

async function thumbnail(page: Page, mapId: string, query: string) {
  const response = await page.request.get(`/api/maps/${mapId}/thumbnail${query}`);
  return { status: response.status(), body: response.ok() ? await response.body() : null };
}

/** Every write to a map's thumbnail the page makes, as it lands. */
function trackWrites(page: Page, mapId: string): { query: string; status: number }[] {
  const writes: { query: string; status: number }[] = [];
  page.on("response", (response) => {
    const request = response.request();
    if (request.method() !== "PUT") return;
    const url = new URL(response.url());
    if (url.pathname !== `/api/maps/${mapId}/thumbnail`) return;
    writes.push({ query: url.search, status: response.status() });
  });
  return writes;
}

async function seedAutoMap(page: Page, name: string, over: Record<string, unknown> = {}) {
  const mapId = await createMap(page, name);
  const layerId = await addLayer(page, mapId, "stations", `SELECT * FROM "${tableName}"`);
  await patchLayer(page, layerId, {
    style: {
      fill: { type: "constant", color: { r: KELP[0], g: KELP[1], b: KELP[2], a: 1 } },
      fillOpacity: 1,
      stroke: { r: KELP[0], g: KELP[1], b: KELP[2], a: 1 },
      strokeOpacity: 1,
      strokeWidth: 0,
      pointRadius: 12,
      opacity: 1,
    },
  });
  if (Object.keys(over).length) await patchMap(page, mapId, over);
  return mapId;
}

async function openBuilder(page: Page, mapId: string) {
  await page.goto(`/maps/${mapId}`);
  await expect(page.getByText("12 features").first()).toBeVisible({ timeout: 30_000 });
}

const themeToggle = (page: Page) =>
  page.getByRole("button", { name: "Switch between dark and light theme" });

const cardImage = (page: Page, mapId: string) =>
  page.locator(`img[src*="/api/maps/${mapId}/thumbnail"]`).first();

/** The card's image as the browser holds it now: its address, whether
 * it loaded, and its decoded stats. */
async function shownImage(page: Page, img: Locator) {
  await expect
    .poll(() => img.evaluate((el: HTMLImageElement) => el.complete && el.naturalWidth > 0), {
      timeout: 15_000,
    })
    .toBe(true);
  const src = await img.evaluate((el: HTMLImageElement) => el.currentSrc || el.src);
  const response = await page.request.get(src);
  expect(response.status()).toBe(200);
  return { src, stats: await imageStats(page, await response.body()) };
}

test.describe("card images by theme", () => {
  test("a map on Auto ends with a light and a dark image that decode to their own grounds with the marks in the same place", async ({
    page,
    context,
  }) => {
    await routeHouse(context);
    await stubStyles(context);
    const errors = trackConsole(page);
    await page.goto("/maps");
    await seedCsv(page, tableName, readFileSync(path.join(FIXTURES_DIR, "stations.csv"), "utf8"));
    const mapId = await seedAutoMap(page, `Auto ${runId}`);
    const writes = trackWrites(page, mapId);

    await openBuilder(page, mapId);
    // The first write carries the live theme (light) and is held; the
    // second carries the other theme under the same cycle and publishes.
    await expect
      .poll(() => writes.map((w) => `${w.status} ${w.query}`).join(" | "), { timeout: 90_000 })
      .toMatch(/204 \?theme=dark&cycle=/);
    const held = writes.find((w) => /theme=light&cycle=/.test(w.query));
    const published = writes.find((w) => /theme=dark&cycle=/.test(w.query));
    expect(held?.status).toBe(202);
    expect(published?.status).toBe(204);
    expect(new URL(`http://x${held!.query}`).searchParams.get("cycle")).toBe(
      new URL(`http://x${published!.query}`).searchParams.get("cycle"),
    );
    // The offscreen host is gone.
    await expect(page.locator("[data-offscreen-ground]")).toHaveCount(0);

    const light = await thumbnail(page, mapId, "?theme=light");
    const dark = await thumbnail(page, mapId, "?theme=dark");
    expect(light.status).toBe(200);
    expect(dark.status).toBe(200);
    expect(light.body!.equals(dark.body!)).toBe(false);
    const l = await imageStats(page, light.body!);
    const d = await imageStats(page, dark.body!);
    // Each carries its own theme's ground.
    expect(closeTo(l.ground, GROUNDS.positron.rgb), `light ground ${l.ground}`).toBe(true);
    expect(closeTo(d.ground, GROUNDS.dark.rgb), `dark ground ${d.ground}`).toBe(true);
    // Both carry the marks, recognisable and in the same place.
    expect(l.marks).toBeGreaterThan(200);
    expect(d.marks).toBeGreaterThan(200);
    expect(Math.abs(l.marks - d.marks) / l.marks).toBeLessThan(0.2);
    expect(Math.abs(l.cx - d.cx)).toBeLessThan(0.01);
    expect(Math.abs(l.cy - d.cy)).toBeLessThan(0.01);
    expect([l.width, l.height]).toEqual([d.width, d.height]);

    await test.step("the Maps card follows a theme toggle with no reload", async () => {
      await page.goto("/maps");
      await page.evaluate(() => {
        (window as unknown as { __thumbnailProbe: number }).__thumbnailProbe = 1;
      });
      const img = cardImage(page, mapId);
      const before = await shownImage(page, img);
      expect(before.src).toMatch(/theme=light/);
      expect(closeTo(before.stats.ground, GROUNDS.positron.rgb)).toBe(true);
      const url = page.url();
      await themeToggle(page).click();
      await expect(img).toHaveAttribute("src", /theme=dark/);
      const after = await shownImage(page, img);
      expect(closeTo(after.stats.ground, GROUNDS.dark.rgb), `card ground ${after.stats.ground}`).toBe(true);
      expect(after.stats.marks).toBeGreaterThan(200);
      expect(page.url()).toBe(url);
      expect(await page.evaluate(() => (window as unknown as { __thumbnailProbe?: number }).__thumbnailProbe)).toBe(1);
      // And back.
      await themeToggle(page).click();
      await expect(img).toHaveAttribute("src", /theme=light/);
      const back = await shownImage(page, img);
      expect(closeTo(back.stats.ground, GROUNDS.positron.rgb)).toBe(true);
    });

    await test.step("the project home's section follows it too", async () => {
      const project = (await page.evaluate(async (name) => {
        const r = await fetch("/api/projects", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ name }),
        });
        if (!r.ok) throw new Error(await r.text());
        return (await r.json()) as { id: string };
      }, `Theme home ${runId}`)).id;
      await page.evaluate(
        async ({ project, mapId }) => {
          const r = await fetch(`/api/projects/${project}/members`, {
            method: "PATCH",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ addMaps: [mapId] }),
          });
          if (!r.ok) throw new Error(await r.text());
        },
        { project, mapId },
      );
      await page.goto(`/projects/${project}`);
      const img = cardImage(page, mapId);
      const before = await shownImage(page, img);
      expect(before.src).toMatch(/theme=light/);
      expect(closeTo(before.stats.ground, GROUNDS.positron.rgb)).toBe(true);
      const url = page.url();
      await themeToggle(page).click();
      await expect(img).toHaveAttribute("src", /theme=dark/);
      const after = await shownImage(page, img);
      expect(closeTo(after.stats.ground, GROUNDS.dark.rgb), `home ground ${after.stats.ground}`).toBe(true);
      expect(page.url()).toBe(url);
      await themeToggle(page).click();
    });

    const unexpected = errors.filter((e) => !isAllowedConsoleError(e.text, e.url));
    expect(unexpected).toEqual([]);
  });

  test("a map on a chosen basemap stores exactly one image, and it serves both themes", async ({
    page,
    context,
  }) => {
    await routeHouse(context);
    await stubStyles(context);
    await page.goto("/maps");
    await seedCsv(page, `${tableName}_s`, readFileSync(path.join(FIXTURES_DIR, "stations.csv"), "utf8"));
    const mapId = await createMap(page, `Streets ${runId}`);
    const layerId = await addLayer(page, mapId, "stations", `SELECT * FROM "${tableName}_s"`);
    await patchLayer(page, layerId, {
      style: {
        fill: { type: "constant", color: { r: KELP[0], g: KELP[1], b: KELP[2], a: 1 } },
        fillOpacity: 1,
        stroke: { r: KELP[0], g: KELP[1], b: KELP[2], a: 1 },
        strokeOpacity: 1,
        strokeWidth: 0,
        pointRadius: 12,
        opacity: 1,
      },
    });
    await patchMap(page, mapId, { basemap: "streets" });
    const writes = trackWrites(page, mapId);
    await openBuilder(page, mapId);
    await expect.poll(() => writes.length, { timeout: 60_000 }).toBeGreaterThan(0);
    // Long enough for a second write to have followed if one were coming:
    // the floor between grounds is ten seconds, a stubbed ground settles
    // at once.
    await page.waitForTimeout(12_000);
    expect(writes.every((w) => w.query === "" && w.status === 204)).toBe(true);
    const light = await thumbnail(page, mapId, "?theme=light");
    const dark = await thumbnail(page, mapId, "?theme=dark");
    const plain = await thumbnail(page, mapId, "");
    expect(light.status).toBe(200);
    expect(light.body!.equals(dark.body!)).toBe(true);
    expect(light.body!.equals(plain.body!)).toBe(true);
    const stats = await imageStats(page, light.body!);
    expect(closeTo(stats.ground, GROUNDS.liberty.rgb), `streets ground ${stats.ground}`).toBe(true);
    expect(stats.marks).toBeGreaterThan(200);
  });

  test("a single image that predates the feature serves both themes and is not regenerated by being listed", async ({
    page,
    context,
  }) => {
    await routeHouse(context);
    await stubStyles(context);
    await page.goto("/maps");
    const mapId = await createMap(page, `Old image ${runId}`);
    const writes = trackWrites(page, mapId);
    // The image a previous version stored: one PNG, no theme.
    const stored = await page.evaluate(async (mapId) => {
      const c = document.createElement("canvas");
      c.width = 64;
      c.height = 36;
      const ctx = c.getContext("2d")!;
      ctx.fillStyle = "#c04080";
      ctx.fillRect(0, 0, 64, 36);
      const blob = await new Promise<Blob>((r) => c.toBlob((b) => r(b!), "image/png"));
      const put = await fetch(`/api/maps/${mapId}/thumbnail`, {
        method: "PUT",
        headers: { "content-type": "image/png" },
        body: blob,
      });
      if (!put.ok) throw new Error(String(put.status));
      return btoa(String.fromCharCode(...new Uint8Array(await blob.arrayBuffer())));
    }, mapId);
    const bytes = Buffer.from(stored, "base64");
    for (const query of ["?theme=light", "?theme=dark", ""]) {
      const got = await thumbnail(page, mapId, query);
      expect(got.status, query).toBe(200);
      expect(got.body!.equals(bytes), query).toBe(true);
    }
    // Listed under both themes: the card shows it, nothing is written.
    await page.goto("/maps");
    const img = cardImage(page, mapId);
    const light = await shownImage(page, img);
    expect(light.stats.ground).toEqual([192, 64, 128]);
    await themeToggle(page).click();
    await expect(img).toHaveAttribute("src", /theme=dark/);
    const dark = await shownImage(page, img);
    expect(dark.stats.ground).toEqual([192, 64, 128]);
    await themeToggle(page).click();
    await page.waitForTimeout(3_000);
    expect(writes.filter((w) => w.status !== 204 || w.query !== "")).toEqual([]);
    expect(writes).toHaveLength(1);
    expect((await thumbnail(page, mapId, "?theme=dark")).body!.equals(bytes)).toBe(true);
  });
});
